function aFecha(txt) {               // 'aaaa-mm-dd hh:mm:ss' (hora local) → Date
    const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})/.exec(String(txt).trim());
