function fechaHistorial(txt) {       // '22/10/2026, 11:03:01 p. m.' o '22/10/2026, 23:03:01'
    const m = /(\d{1,2})\/(\d{1,2})\/(\d{4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap])?/i.exec(String(txt));
    if (!m) return null;
    let h = +m[4];
    if (m[7]) { const pm = m[7].toLowerCase() === 'p'; if (pm && h < 12) h += 12; if (!pm && h === 12) h = 0; }
    return new Date(+m[3], +m[2] - 1, +m[1], h, +m[5], +(m[6] || 0));
}
function camposCSV(linea) {          // separa una línea CSV respetando comillas
    const out = []; let cur = '', q = false;
    for (let i = 0; i < linea.length; i++) {
        const c = linea[i];
        if (q) { if (c === '"' && linea[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
        else if (c === '"') q = true; else if (c === ',') { out.push(cur); cur = ''; } else cur += c;
    }
    out.push(cur);
    return out;
}
const numOnull = (s) => { if (s === undefined || String(s).trim() === '') return null; const v = Number(s); return isFinite(v) ? v : null; };

// ---------- 1) Lecturas del rango ----------
const lecturas = leer(ARCH_LECTURAS).split(/\r?\n/).slice(1)
    .filter((l) => l.trim() !== '')
    .map((l) => {
        const c = l.split(',');
        return { t: aFecha(c[0]), v: c.slice(1, 9).map(numOnull), riego: c[9] === '1' ? 1 : 0 };
    })
    .filter((r) => r.t && r.t >= desde && r.t <= ahora)
    .sort((a, b) => a.t - b.t);

if (lecturas.length === 0) {
    return [null, aviso(false, 'No hay lecturas guardadas en ese rango todavía (se guarda una por minuto).')];
}

// ---------- 2) Riegos del rango ----------
const riegos = leer(ARCH_RIEGOS).split(/\r?\n/).slice(1)
    .filter((l) => l.trim() !== '')
    .map((l) => { const c = camposCSV(l); return { inicio: aFecha(c[0]), fin: aFecha(c[1]), seg: Number(c[2]) || 0, origen: c[3] || '', razon: c[4] || '', cierre: c[5] || '' }; })
    .filter((r) => r.inicio && r.fin && r.fin >= desde && r.inicio <= ahora)
    .sort((a, b) => a.inicio - b.inicio);
const segRiego = riegos.reduce((a, r) => a + r.seg, 0);
const textoOrigen = (o) => o === 'automatico' ? 'Automático' : (o === 'manual' ? 'Manual' : (o || '—'));

// ---------- 3) Alertas del rango (historial en memoria de Node-RED) ----------
const alertas = (global.get('historialAlertas') || [])
    .map((a) => ({ t: fechaHistorial(a.fecha), titulo: a.titulo || '', evento: a.evento || '', detalle: a.detalle || '' }))
    .filter((a) => a.t && a.t >= desde && a.t <= ahora)
    .sort((a, b) => a.t - b.t);
const nActivadas = alertas.filter((a) => a.evento === 'Activada').length;

// ---------- 4) Estadísticas por variable ----------
const infS = Number(global.get('limiteInfHumSustrato') ?? 25);
const supS = Number(global.get('limiteSupHumSustrato') ?? 70);
const supT = Number(global.get('limiteSupTemp') ?? 28);
const infH = Number(global.get('limiteInfHumAmb') ?? 40);
const supH = Number(global.get('limiteSupHumAmb') ?? 80);

const VARS = [];
for (let i = 0; i < 6; i++) {
    VARS.push({ nombre: 'Sensor ' + (i + 1) + ' · Sustrato', unidad: '%', idx: i,
        rango: infS + '–' + supS + ' %', enRango: (v) => v >= infS && v <= supS });
}
VARS.push({ nombre: 'Temperatura ambiente', unidad: '°C', idx: 6, rango: 'máx. ' + supT + ' °C', enRango: (v) => v <= supT });
VARS.push({ nombre: 'Humedad relativa ambiente', unidad: '%', idx: 7, rango: infH + '–' + supH + ' %', enRango: (v) => v >= infH && v <= supH });

VARS.forEach((V) => {
    const vals = lecturas.map((r) => r.v[V.idx]).filter((v) => v !== null);
    V.n = vals.length;
    V.min = vals.length ? vals.reduce((a, b) => Math.min(a, b)) : null;
    V.max = vals.length ? vals.reduce((a, b) => Math.max(a, b)) : null;
    V.prom = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
    V.pct = vals.length ? vals.filter(V.enRango).length / vals.length : null;
    V.ultima = vals.length ? vals[vals.length - 1] : null;
});

// intervalo típico entre filas (para cortar la línea de la gráfica cuando hay huecos)
const difs = [];
for (let i = 1; i < lecturas.length; i++) difs.push(lecturas[i].t - lecturas[i - 1].t);
difs.sort((a, b) => a - b);
const pasoMs = difs.length ? difs[Math.floor(difs.length / 2)] : 60e3;
const t0 = lecturas[0].t.getTime();
const t1 = Math.max(lecturas[lecturas.length - 1].t.getTime(), t0 + 10 * 60e3);

const textoPeriodo = fechaHora(desde) + ' a ' + fechaHora(ahora) + ' (' + nombreRango(horas) + ')';
const textoFrecuencia = Math.max(1, Math.round(pasoMs / 60e3)) + ' min';
const sello = ahora.getFullYear() + '-' + p2(ahora.getMonth() + 1) + '-' + p2(ahora.getDate()) + '_' + p2(ahora.getHours()) + p2(ahora.getMinutes());
const base = 'Reporte_Orquideario_UVG_' + sello + '_' + (horas < 24 ? horas + 'h' : Math.round(horas / 24) + 'd');

// ================= PDF =================
const C = {
    titulo: '#1c1f22', texto: '#33373b', etiqueta: '#5b6168', gris: '#8a9096',
    linea: '#dde1e5', rejilla: '#eceff1', eje: '#c5cbd0', acento: '#1F4D3A',
    riego: '#e6f0f5', lim: '#8a9096', activada: '#a94442', resuelta: '#4f7d5a'
};
const COLORES = ['#1F4D3A', '#4A6F8A', '#8A5A3B', '#6B8F5E', '#8E4F6E', '#3F7F7A'];

function generarPDF() {
    return new Promise((resolve, reject) => {
        const M = 43, TOP = 100;
        const doc = new PDFDocument({ size: 'A4', margins: { top: TOP, bottom: 60, left: M, right: M }, bufferPages: true,
            info: { Title: 'Reporte de monitoreo — ' + LUGAR, Author: nombre } });
        const partes = [];
        doc.on('data', (c) => partes.push(c));
        doc.on('end', () => resolve(Buffer.concat(partes)));
        doc.on('error', reject);

        const W = doc.page.width - 2 * M;
        const fondo = () => doc.page.height - doc.page.margins.bottom;
        const espacio = (h) => { if (doc.y + h > fondo()) doc.addPage(); };
        let logo = null;
        try { if (fs.existsSync(ARCH_LOGO)) logo = fs.readFileSync(ARCH_LOGO); } catch (e) { logo = null; }

        // ---- Encabezado en todas las páginas ----
        function cabecera() {
            if (logo) { try { doc.image(logo, M, 26, { fit: [48, 46] }); } catch (e) { /* logo inválido: se omite */ } }
            doc.font('Helvetica').fontSize(8.5).fillColor(C.gris)
                .text('Universidad del Valle de Guatemala · Jardín Botánico', M, 34, { width: W, align: 'right', lineBreak: false });
            doc.moveTo(M, 80).lineTo(M + W, 80).lineWidth(0.6).strokeColor(C.linea).stroke();
            doc.x = M; doc.y = TOP;
        }
        doc.on('pageAdded', cabecera);
        cabecera();

        function seccion(titulo, minimo) {
            espacio(minimo || 70);
            doc.font('Helvetica-Bold').fontSize(13).fillColor(C.titulo).text(titulo, M, doc.y + 12);
            doc.y += 8;
        }

        function tabla(cols, filas) {
            const tam = 8.5, PAD = 6;
            const altoFila = (fila, bold) => {
                doc.font(bold ? 'Helvetica-Bold' : 'Helvetica').fontSize(bold ? 8 : tam);
                let h = 0;
                cols.forEach((c, i) => { h = Math.max(h, doc.heightOfString(String(fila[i]), { width: c.w - 2 * PAD })); });
                return h + (bold ? 13 : 10);
            };
            const encabezado = (y) => {
                const h = altoFila(cols.map((c) => c.t), true);
                doc.moveTo(M, y).lineTo(M + W, y).lineWidth(0.6).strokeColor(C.linea).stroke();
                let x = M;
                doc.font('Helvetica-Bold').fontSize(8).fillColor(C.etiqueta);
                cols.forEach((c) => { doc.text(c.t, x + PAD, y + 6.5, { width: c.w - 2 * PAD, align: c.a || 'left' }); x += c.w; });
                doc.moveTo(M, y + h).lineTo(M + W, y + h).lineWidth(0.6).strokeColor(C.linea).stroke();
                return y + h;
            };
            let y = doc.y;
            if (y + 60 > fondo()) { doc.addPage(); y = doc.y; }
            y = encabezado(y);
            filas.forEach((f) => {
                const h = altoFila(f, false);
                if (y + h > fondo()) { doc.addPage(); y = encabezado(doc.y); }
                let x = M;
                cols.forEach((c, i) => {
                    const est = (f.estilos && f.estilos[i]) || {};
                    doc.font(est.bold ? 'Helvetica-Bold' : 'Helvetica').fontSize(tam).fillColor(est.color || C.texto)
                        .text(String(f[i]), x + PAD, y + 5, { width: c.w - 2 * PAD, align: c.a || 'left' });
                    x += c.w;
