            const pot = Math.pow(10, Math.floor(Math.log10(crudo)));
            const paso = [1, 2, 2.5, 5, 10].map((k) => k * pot).find((p) => p >= crudo) || 10 * pot;
            return { min: Math.floor(minV / paso) * paso, max: Math.ceil(maxV / paso) * paso, paso: paso };
        }

        function marcasTiempo() {      // marcas en horas "redondas" (o días) según el largo del periodo
            const MIN = 60e3;
            const pasos = [5, 10, 15, 30, 60, 120, 180, 360, 720, 1440, 2880, 4320, 10080].map((m) => m * MIN);
            const paso = pasos.find((p) => (t1 - t0) / p <= 7) || pasos[pasos.length - 1];
            const d = new Date(t0);
            let t = paso >= 1440 * MIN ? new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
                                       : new Date(d.getFullYear(), d.getMonth(), d.getDate(), d.getHours()).getTime();
            while (t < t0) t += paso;
            const lista = [];
            for (; t <= t1; t += paso) lista.push(t);
            const multiDia = (t1 - t0) > 24 * 3600e3;
            const etiqueta = (x) => { const k = new Date(x); return paso >= 1440 * MIN ? p2(k.getDate()) + '/' + p2(k.getMonth() + 1) : (multiDia ? p2(k.getDate()) + '/' + p2(k.getMonth() + 1) + ' ' + hora(k) : hora(k)); };
            return lista.map((x) => ({ t: x, txt: etiqueta(x) }));
        }

        function reducir(puntos, maximo) {   // promedia en bloques si hay demasiados puntos
            if (puntos.length <= maximo) return puntos;
            const n = Math.ceil(puntos.length / maximo), out = [];
            for (let i = 0; i < puntos.length; i += n) {
                const b = puntos.slice(i, i + n), v = b.filter((p) => p[1] !== null);
                out.push([b[Math.floor(b.length / 2)][0], v.length ? v.reduce((a, p) => a + p[1], 0) / v.length : null]);
            }
