        }

        // { subtitulo, ejeY, alto, series:[{nombre,color,idx}], limites:[{v,txt}], fijo:{min,max,paso}, bandas, leyenda }
        function grafica(o) {
            const alto = o.alto || 170;
            espacio(alto + (o.subtitulo ? 22 : 0) + (o.leyenda ? 48 : 26));
            if (o.subtitulo) { doc.font('Helvetica-Bold').fontSize(9.5).fillColor(C.titulo).text(o.subtitulo, M, doc.y + 4); }
            const top = doc.y + 12, izq = M + 40, der = M + W - 6, ancho = der - izq, abajo = top + alto;

            let E = o.fijo;
            if (!E) {
                let lo = Infinity, hi = -Infinity;
                o.series.forEach((s) => lecturas.forEach((r) => { const v = r.v[s.idx]; if (v !== null) { lo = Math.min(lo, v); hi = Math.max(hi, v); } }));
                (o.limites || []).forEach((l) => { lo = Math.min(lo, l.v); hi = Math.max(hi, l.v); });
                if (!isFinite(lo)) { lo = 0; hi = 1; }
