                doc.fontSize(7.5).fillColor(C.gris).text(o.ejeY, M + 4 - alto / 2, top + alto / 2 - 4, { width: alto, align: 'center', lineBreak: false });
                doc.restore();
            }
            // ejes
            doc.moveTo(izq, top).lineTo(izq, abajo).lineTo(der, abajo).lineWidth(0.6).strokeColor(C.eje).stroke();
            // marcas de tiempo
            marcasTiempo().forEach((m) => {
                const x = px(m.t);
                doc.moveTo(x, abajo).lineTo(x, abajo + 3).lineWidth(0.5).strokeColor(C.eje).stroke();
                doc.fillColor(C.gris).fontSize(7.5).text(m.txt, x - 30, abajo + 6, { width: 60, align: 'center', lineBreak: false });
            });
            // límites configurados
            (o.limites || []).forEach((l) => {
                if (l.v < E.min || l.v > E.max) return;
                const y = py(l.v);
                doc.moveTo(izq, y).lineTo(der, y).dash(2.5, { space: 2.5 }).lineWidth(0.7).strokeColor(C.lim).stroke().undash();
                doc.fontSize(7).fillColor(C.gris).text(l.txt, der - 90, y - 9, { width: 88, align: 'right', lineBreak: false });
            });
            // series
            doc.save();
            doc.rect(izq, top - 2, ancho + 4, alto + 4).clip();
            o.series.forEach((s) => {
                const pts = reducir(lecturas.map((r) => [r.t.getTime(), r.v[s.idx]]), 500);
                const corte = Math.max(pasoMs * 3, (t1 - t0) / 500 * 3);
                let tramo = [], ultimo = null;
                const cerrar = () => {
                    if (tramo.length > 1) {
                        doc.moveTo(tramo[0][0], tramo[0][1]);
                        tramo.slice(1).forEach((p) => doc.lineTo(p[0], p[1]));
                        doc.lineWidth(1.4).lineJoin('round').lineCap('round').strokeColor(s.color).stroke();
                    } else if (tramo.length === 1) doc.circle(tramo[0][0], tramo[0][1], 1.2).fill(s.color);
                    tramo = [];
                };
                let tAnt = null;
                pts.forEach((p) => {
                    if (p[1] === null) { cerrar(); tAnt = null; return; }
