                items.forEach((it, i) => {
                    const lx = M + 10 + (i % 6) * col, ly = yFin + 8 + Math.floor(i / 6) * 14;
                    doc.moveTo(lx, ly + 3).lineTo(lx + 16, ly + 3).lineWidth(1.6).strokeColor(it.color).stroke();
                    doc.fillColor(C.etiqueta).text(it.txt, lx + 22, ly, { lineBreak: false });
                });
                yFin += 8 + Math.ceil(items.length / 6) * 14;
                if ((o.bandas || []).length) {
                    doc.rect(M + 10, yFin + 4, 12, 8).fill(C.riego);
                    doc.fillColor(C.etiqueta).text('Momentos de riego', M + 28, yFin + 4, { lineBreak: false });
                    yFin += 16;
                }
            }
            doc.x = M; doc.y = yFin + 4;
        }

        // ---- Título ----
        doc.font('Helvetica-Bold').fontSize(22).fillColor(C.titulo).text('Reporte de monitoreo', M, TOP);
        doc.moveDown(0.15);
        doc.font('Helvetica').fontSize(11).fillColor(C.acento).text(LUGAR + ' · Sistema de riego automatizado', M, doc.y);

        // ---- Datos del reporte (dos columnas) ----
        const col2 = M + W * 0.51;
        const dato = (x, y, etiqueta, valor) => {
            doc.font('Helvetica-Bold').fontSize(8.5).fillColor(C.etiqueta).text(etiqueta + ':', x, y, { continued: true })
               .font('Helvetica').fillColor(C.texto).text('   ' + valor, { lineBreak: false });
        };
        let y = doc.y + 18;
        dato(M, y, 'Periodo', textoPeriodo);
        dato(col2, y, 'Generado por', nombre);
        y += 19;
        dato(M, y, 'Fecha de generación', fechaHora(ahora));
        dato(col2, y, 'Frecuencia de registro', textoFrecuencia);
        y += 26;

        // ---- Indicadores ----
        const kpis = [
            ['Lecturas', String(lecturas.length)],
            ['Riegos', String(riegos.length)],
            ['Tiempo total de riego', riegos.length ? dur(segRiego) : '0 s'],
            ['Alertas activadas', String(nActivadas)]
        ];
        const kw = W / 4, kh = 48;
        doc.moveTo(M, y).lineTo(M + W, y).lineWidth(0.6).strokeColor(C.linea).stroke();
        kpis.forEach((k, i) => {
            const kx = M + i * kw;
            if (i > 0) doc.moveTo(kx, y + 8).lineTo(kx, y + kh - 8).lineWidth(0.6).strokeColor(C.linea).stroke();
            doc.font('Helvetica').fontSize(8.5).fillColor(C.etiqueta).text(k[0], kx + 10, y + 10, { width: kw - 20, lineBreak: false });
            doc.font('Helvetica-Bold').fontSize(14).fillColor(C.titulo).text(k[1], kx + 10, y + 24, { width: kw - 20, lineBreak: false });
        });
        doc.moveTo(M, y + kh).lineTo(M + W, y + kh).lineWidth(0.6).strokeColor(C.linea).stroke();
        doc.x = M; doc.y = y + kh + 4;

        // ---- 1. Resumen ----
        seccion('1. Resumen por variable');
        tabla([{ t: 'Variable', w: 122 }, { t: 'Rango configurado', w: 92 }, { t: 'Mín.', w: 44, a: 'right' }, { t: 'Prom.', w: 48, a: 'right' },
               { t: 'Máx.', w: 48, a: 'right' }, { t: 'Última', w: 48, a: 'right' }, { t: 'En rango', w: 54, a: 'right' }, { t: 'Lecturas', w: W - 456, a: 'right' }],
            VARS.map((V) => [V.nombre, V.rango, f1(V.min), f1(V.prom), f1(V.max), f1(V.ultima),
                V.pct === null ? '—' : Math.round(V.pct * 100) + ' %', String(V.n)]));

        // ---- 2. Sustrato ----
        seccion('2. Humedad del sustrato', 250);
        grafica({ alto: 160, ejeY: 'Humedad (%)', fijo: { min: 0, max: 100, paso: 20 }, bandas: riegos, leyenda: true,
            series: [0, 1, 2, 3, 4, 5].map((i) => ({ nombre: 'Sensor ' + (i + 1), color: COLORES[i], idx: i })),
            limites: [{ v: supS, txt: 'Máx. ' + supS + ' %' }, { v: infS, txt: 'Mín. ' + infS + ' %' }] });

        // ---- 3. Ambiente (página 2) ----
        doc.addPage();
        seccion('3. Condiciones ambientales');
        grafica({ subtitulo: 'Temperatura ambiente (°C)', ejeY: 'Temperatura (°C)', alto: 70,
            series: [{ nombre: 'Temperatura', color: '#B5652F', idx: 6 }], limites: [{ v: supT, txt: 'Máx. ' + supT + ' °C' }] });
        doc.y += 6;
        grafica({ subtitulo: 'Humedad relativa ambiente (%)', ejeY: 'Humedad (%)', alto: 70,
            series: [{ nombre: 'Humedad relativa', color: '#4A6F8A', idx: 7 }],
            limites: [{ v: supH, txt: 'Máx. ' + supH + ' %' }, { v: infH, txt: 'Mín. ' + infH + ' %' }] });

        // ---- 4. Riegos ----
        seccion('4. Riegos realizados');
        if (!riegos.length) {
            doc.font('Helvetica').fontSize(9).fillColor(C.texto).text('No hubo riegos en este periodo.', M, doc.y + 2);
        } else {
            tabla([{ t: 'Inicio', w: 112 }, { t: 'Duración', w: 66 }, { t: 'Origen', w: 70 }, { t: 'Motivo', w: W - 360 }, { t: 'Cierre', w: 112 }],
                riegos.map((r) => {
                    const motivo = (r.razon || '—') + (r.cierre && r.cierre !== 'Por orden de Node-RED' ? ' · ' + r.cierre : '');
                    return [fechaHoraS(r.inicio), dur(r.seg), textoOrigen(r.origen), motivo, fechaHoraS(r.fin)];
                }));
        }

        // ---- 5. Alertas ----
        seccion('5. Alertas');
        if (!alertas.length) {
            doc.font('Helvetica').fontSize(9).fillColor(C.texto).text('No se registraron alertas en este periodo.', M, doc.y + 2);
        } else {
            tabla([{ t: 'Fecha', w: 112 }, { t: 'Alerta', w: 140 }, { t: 'Estado', w: 66 }, { t: 'Detalle', w: W - 318 }],
                alertas.map((a) => {
                    const f = [fechaHoraS(a.t), a.titulo, a.evento, a.detalle];
                    f.estilos = []; f.estilos[2] = { bold: true, color: a.evento === 'Activada' ? C.activada : C.resuelta };
                    return f;
                }));
        }
        doc.font('Helvetica').fontSize(8).fillColor(C.gris)
            .text('Las alertas se toman del historial del sistema desde su último reinicio.', M, doc.y + 14, { width: W });

        // ---- Número de página (y marca de agua si aplica) ----
        const rango = doc.bufferedPageRange();
        for (let i = rango.start; i < rango.start + rango.count; i++) {
            doc.switchToPage(i);
            const mb = doc.page.margins.bottom;
            doc.page.margins.bottom = 0;
            if (MARCA) {
                doc.save();
                doc.rotate(-35, { origin: [doc.page.width / 2, doc.page.height / 2] });
                doc.font('Helvetica-Bold').fontSize(46).fillColor('#d92d20').fillOpacity(0.12)
                    .text(MARCA, 0, doc.page.height / 2 - 25, { width: doc.page.width, align: 'center', lineBreak: false });
                doc.restore();
                doc.fillOpacity(1);
            }
            doc.font('Helvetica').fontSize(8.5).fillColor(C.gris)
                .text(String(i - rango.start + 1), M, doc.page.height - 34, { width: W, align: 'center', lineBreak: false });
            doc.page.margins.bottom = mb;
        }
        doc.end();
    });
}

// ================= EXCEL =================
// ExcelJS guarda las fechas como UTC: paso la hora local "tal cual" para que Excel muestre la hora correcta
const xFecha = (d) => new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate(), d.getHours(), d.getMinutes(), d.getSeconds()));

async function generarExcel() {
    const wb = new ExcelJS.Workbook();
    wb.creator = nombre;
    wb.created = ahora;
    const encabezar = (fila) => {
        fila.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        fila.eachCell((c) => { c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F4D3A' } }; c.alignment = { vertical: 'middle' }; });
    };

    // Hoja Resumen
    const r = wb.addWorksheet('Resumen');
    r.columns = [{ width: 30 }, { width: 20 }, { width: 11 }, { width: 11 }, { width: 11 }, { width: 11 }, { width: 11 }, { width: 13 }];
    r.addRow(['Reporte de monitoreo — ' + LUGAR]).font = { bold: true, size: 14 };
    if (MARCA) r.addRow([MARCA]).font = { bold: true, color: { argb: 'FFD92D20' } };
    r.addRow(['Periodo', textoPeriodo]);
    r.addRow(['Generado por', nombre]);
    r.addRow(['Fecha de generación', fechaHora(ahora)]);
    r.addRow(['Frecuencia de registro', textoFrecuencia]);
    r.addRow(['Lecturas', lecturas.length]);
    r.addRow(['Riegos', riegos.length]);
    r.addRow(['Tiempo total de riego (s)', segRiego]);
    r.addRow(['Alertas activadas', nActivadas]);
    r.addRow([]);
    encabezar(r.addRow(['Variable', 'Rango configurado', 'Mínimo', 'Promedio', 'Máximo', 'Última', 'En rango', 'Lecturas']));
    VARS.forEach((V) => {
        const fila = r.addRow([V.nombre + ' (' + V.unidad + ')', V.rango, V.min, V.prom === null ? null : Math.round(V.prom * 10) / 10, V.max, V.ultima, V.pct, V.n]);
        [3, 4, 5, 6].forEach((k) => { fila.getCell(k).numFmt = '0.0'; });
        fila.getCell(7).numFmt = '0%';
    });

    // Hoja Lecturas (todas las filas del rango)
    const l = wb.addWorksheet('Lecturas', { views: [{ state: 'frozen', ySplit: 1 }] });
    l.columns = [{ header: 'Fecha y hora', key: 't', width: 18, style: { numFmt: 'dd/mm/yyyy hh:mm' } }]
        .concat([1, 2, 3, 4, 5, 6].map((i) => ({ header: 'Sensor ' + i + ' (%)', key: 's' + i, width: 12, style: { numFmt: '0.0' } })))
        .concat([{ header: 'Temperatura (°C)', key: 'ta', width: 15, style: { numFmt: '0.0' } },
                 { header: 'HR ambiente (%)', key: 'ha', width: 15, style: { numFmt: '0.0' } },
                 { header: 'Riego', key: 'rg', width: 8 }]);
    encabezar(l.getRow(1));
    lecturas.forEach((x) => l.addRow({ t: xFecha(x.t), s1: x.v[0], s2: x.v[1], s3: x.v[2], s4: x.v[3], s5: x.v[4], s6: x.v[5], ta: x.v[6], ha: x.v[7], rg: x.riego ? 'ON' : 'OFF' }));
    l.autoFilter = { from: 'A1', to: 'J1' };

    // Hoja Riegos
    const g = wb.addWorksheet('Riegos', { views: [{ state: 'frozen', ySplit: 1 }] });
    g.columns = [{ header: 'Inicio', key: 'i', width: 19, style: { numFmt: 'dd/mm/yyyy hh:mm:ss' } }, { header: 'Cierre', key: 'f', width: 19, style: { numFmt: 'dd/mm/yyyy hh:mm:ss' } },
        { header: 'Duración (s)', key: 'd', width: 12 }, { header: 'Origen', key: 'o', width: 12 }, { header: 'Motivo', key: 'm', width: 50 }, { header: 'Tipo de cierre', key: 'c', width: 42 }];
    encabezar(g.getRow(1));
    riegos.forEach((x) => g.addRow({ i: xFecha(x.inicio), f: xFecha(x.fin), d: x.seg, o: textoOrigen(x.origen), m: x.razon, c: x.cierre }));

    // Hoja Alertas
    const a = wb.addWorksheet('Alertas', { views: [{ state: 'frozen', ySplit: 1 }] });
    a.columns = [{ header: 'Fecha', key: 't', width: 19, style: { numFmt: 'dd/mm/yyyy hh:mm:ss' } }, { header: 'Alerta', key: 'a', width: 34 },
        { header: 'Estado', key: 'e', width: 11 }, { header: 'Detalle', key: 'd', width: 60 }];
    encabezar(a.getRow(1));
    alertas.forEach((x) => a.addRow({ t: xFecha(x.t), a: x.titulo, e: x.evento, d: x.detalle }));

    return Buffer.from(await wb.xlsx.writeBuffer());
}

// ================= CORREO =================
function cuerpoHTML() {
    const td = 'style="padding:5px 10px;border-bottom:1px solid #e5e8eb;text-align:right"';
    const tdl = 'style="padding:5px 10px;border-bottom:1px solid #e5e8eb;text-align:left"';
    const filas = VARS.map((V) => '<tr><td ' + tdl + '>' + V.nombre + '</td><td ' + td + '>' + f1(V.prom) + ' ' + V.unidad +
        '</td><td ' + td + '>' + f1(V.min) + ' – ' + f1(V.max) + '</td><td ' + td + '>' + (V.pct === null ? '—' : Math.round(V.pct * 100) + ' %') + '</td></tr>').join('');
    return '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#33373b">' +
        (MARCA ? '<p style="color:#d92d20;font-weight:bold">' + MARCA + '</p>' : '') +
        '<p>Reporte de monitoreo del <b>' + LUGAR + '</b>.</p>' +
        '<p>Periodo: ' + textoPeriodo + '<br>Generado por: ' + nombre + '<br>Lecturas: ' + lecturas.length + ' · Riegos: ' + riegos.length +
        (riegos.length ? ' (' + dur(segRiego) + ' en total)' : '') + ' · Alertas activadas: ' + nActivadas + '</p>' +
        '<table style="border-collapse:collapse;font-size:13px"><tr><th ' + tdl + '>Variable</th><th ' + td + '>Promedio</th><th ' + td + '>Mín – Máx</th><th ' + td + '>En rango</th></tr>' +
        filas + '</table>' +
        '<p>Se adjuntan el PDF con el resumen y las gráficas, y el Excel con todas las lecturas, riegos y alertas del periodo.</p></div>';
}

node.status({ fill: 'blue', shape: 'ring', text: 'Generando reporte...' });
Promise.all([generarPDF(), generarExcel()])
    .then((res) => {
        const correoMsg = {
            to: correo,
            topic: 'Reporte de monitoreo — Orquideario Jardín Botánico UVG — ' + nombreRango(horas) + ' — ' + fecha(ahora),
            payload: cuerpoHTML(),
            attachments: [
                { filename: base + '.pdf', content: res[0], contentType: 'application/pdf' },
                { filename: base + '.xlsx', content: res[1], contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }
            ]
        };
        node.status({ fill: 'green', shape: 'dot', text: nombre + ' → ' + correo + ' (' + lecturas.length + ' lecturas)' });
        node.send([correoMsg, aviso(true, 'Reporte generado (' + lecturas.length + ' lecturas) y enviado a ' + correo + '.')]);
        node.done();
    })
    .catch((e) => {
        node.status({ fill: 'red', shape: 'ring', text: 'Error al generar' });
        node.error('Reporte: ' + e.message, msg);
        node.send([null, aviso(false, 'Error al generar el reporte: ' + e.message)]);
        node.done();
    });
return null;
